(function(){
'use strict';
const L=(z,e)=>RWI18n.lang==='en'?e:z,T=x=>typeof x==='object'?x[RWI18n.lang]||x.zh:x,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,level='all',category='all',active;
async function load(){if(!data){const r=await fetch('academy.json');if(!r.ok)throw Error('Tutorial download failed');data=await r.json()}return data}
async function mount(id){const main=document.querySelector('#main');main.innerHTML='<div class="section-wrap">'+L('正在打开教程','Loading tutorials')+'</div>';try{await load();if(id)lesson(id);else listing()}catch(e){main.textContent=e.message}}
function listing(){active=null;const cats=[...new Set(data.lessons.map(x=>T(x.category)))];document.querySelector('#main').innerHTML=`<div class="section-wrap"><div class="eyebrow">MOD ACADEMY / LEARN BY BUILDING</div><h1>${L('一步一步，做出自己的模组','Build a mod, one step at a time')}</h1><p class="heading-sub">${L('24 章实作课程，8 个完整项目，从第一个单位学到多单位联动，代码就在每一课里','24 practical chapters and 8 complete projects, from a first unit to multi-unit systems, with code in every lesson')}</p><div class="learning-filters">${[['all','全部课程','All lessons'],['beginner','新手','Beginner'],['intermediate','进阶','Intermediate'],['veteran','老手','Veteran'],['ultimate','终极','Mastery']].map(([id,z,e])=>`<button data-ac="level" data-value="${id}" class="${level===id?'active':''}">${L(z,e)}</button>`).join('')}</div><label class="learning-category">${L('按类型查看','Browse by topic')}<select id="academy-category"><option value="all">${L('全部类型','All topics')}</option>${cats.map(c=>`<option value="${E(c)}" ${category===c?'selected':''}>${E(c)}</option>`).join('')}</select></label>${['beginner','intermediate','veteran','ultimate'].filter(k=>level==='all'||level===k).map((k,i)=>{const lessons=data.lessons.filter(l=>l.path===k&&(category==='all'||T(l.category)===category));if(!lessons.length)return '';return `<section><div class="lesson-path-head"><strong>${['beginner','intermediate','veteran','ultimate'].indexOf(k)+1}</strong><div><h2>${({beginner:L('新手 · 第一个可用单位','Beginner · Your first working unit'),intermediate:L('进阶 · 让单位拥有特色','Intermediate · Add distinctive behavior'),veteran:L('老手 · 深入单位协作','Veteran · Deeper unit systems'),ultimate:L('终极 · 把系统组合起来','Mastery · Bring the systems together')})[k]}</h2><p>${({beginner:L('认识文件、贴图和武器，把想法放进游戏','Learn files, sprites and weapons, then try your ideas in game'),intermediate:L('学习动作、资源、继承和动画','Explore actions, resources, inheritance and animation'),veteran:L('连接消息、资源、运输与火控','Connect messages, resources, transport and fire control'),ultimate:L('编排状态、协作与地图事件，完成可分享项目','Combine states, cooperation and map events into a shareable project')})[k]}</p></div></div><div class="course-grid">${lessons.map(l=>`<a class="course-card" href="#learn/${l.id}"><div class="course-tags"><span>${E(T(l.category))}</span><span>${l.durationMinutes} ${L('分钟','min')}</span></div><small>${L('第','Chapter ')} ${l.chapter} ${L('章','')}</small><h3>${E(T(l.title))}</h3><p>${E(T(l.summary))}</p><strong>${L('开始这一课 →','Open chapter →')}</strong></a>`).join('')}</div></section>`}).join('')}<section class="settings-card"><h2>${L('补充阅读与原始手册','Further reading and original handbook')}</h2><p>${L('原有 8 篇基础教程和 18 章参考手册继续保留，遇到具体参数可以随时查询','The original 8 guides and 18-chapter handbook remain available for reference')}</p><div class="detail-actions"><a class="btn btn-plain" href="#legacy-tutorials">${L('基础速读教程','Original quick guides')}</a><a class="btn btn-plain" href="#manual">${L('完整中文手册','Original Chinese handbook')}</a><a class="btn btn-dark" href="#ai-help">${L('有疑问，问 AI','Ask the assistant')}</a></div></section></div>`}
function code(text,file){return `<div class="code-panel"><div class="code-panel-head"><span>${E(file||L('教学片段','Teaching snippet'))}</span></div><pre data-no-translate><code>${E(text)}</code></pre></div>`}
function lesson(id){const l=data.lessons.find(x=>x.id===id);if(!l){document.querySelector('#main').innerHTML='<div class="section-wrap">'+L('没有找到这一章','Chapter not found')+'</div>';return}active=l;const project=data.projects.find(x=>x.id===l.projectId),i=data.lessons.indexOf(l);document.title=T(l.title)+' · '+L('铁锈战争模组工坊','Rusted Warfare Mod Workshop');document.querySelector('#main').innerHTML=`<div class="section-wrap"><a href="#tutorials" class="text-link">← ${L('全部课程','All courses')}</a><div class="eyebrow">${E(l.path.toUpperCase())} / CHAPTER ${l.chapter}</div><h1>${E(T(l.title))}</h1><p>${E(T(l.summary))}</p></div><div class="article-layout"><aside class="article-toc"><div class="side-label">${L('课程目录','CHAPTERS')}</div>${data.lessons.filter(x=>x.path===l.path).map(x=>`<a href="#learn/${x.id}" ${x.id===id?'aria-current="page"':''}>${x.chapter} ${E(T(x.title))}</a>`).join('')}<a href="#ai-help">✦ ${L('问帮助 AI','Ask the assistant')}</a></aside><article class="article-main"><div class="detail-meta"><span class="tag">${E(T(l.level))}</span><span>${E(T(l.category))}</span><span>${l.durationMinutes} ${L('分钟','min')}</span></div>${project?`<div class="lesson-download"><h3>${L('本章配套模组：','Companion mod: ')}${E(T(project.title))}</h3><p>${E(T(project.description))}</p><div class="detail-actions"><button class="btn btn-dark" data-ac="download" data-id="${project.id}">${L('下载完整 .rwmod','Download complete .rwmod')}</button><button class="btn btn-plain" data-ac="source" data-id="${project.id}">${L('查看项目全部代码','View all project code')}</button></div><small>${L('代码与引用按 1.15 手册核对，导入后请按课程步骤测试实际表现','Checked against the 1.15 reference, follow the lesson steps to test behavior in game')}</small></div>`:''}${l.sections.map((s,n)=>`<section><h2><span class="small-mono">${n+1} / </span>${E(T(s.title))}</h2><p>${E(T(s.body))}</p>${s.code?code(s.code,s.file)+`<div class="lesson-code-actions"><button class="btn btn-small btn-plain" data-ac="copy" data-index="${n}">${L('复制这段代码','Copy code')}</button></div>`:''}${s.steps?`<ol class="chapter-steps">${s.steps.map(x=>`<li>${E(T(x))}</li>`).join('')}</ol>`:''}</section>`).join('')}<div class="lesson-check"><strong>${L('学完应该能做到','What you should be able to do')}</strong><p>${E(T(l.outcome))}</p></div><div class="lesson-pitfall"><strong>${L('动手练习','Try it yourself')}</strong><p>${E(T(l.exercise))}</p></div><div id="academy-source"></div><div class="detail-actions"><button class="btn btn-dark" data-action="complete-lesson" data-id="${l.id}">${L('✓ 标记本章完成','✓ Mark chapter complete')}</button><a class="btn btn-plain" href="#ai-help">${L('让 AI 帮我理解','Ask the assistant')}</a></div><div class="article-nav">${i?`<a href="#learn/${data.lessons[i-1].id}">← ${L('上一章','Previous chapter')}</a>`:'<a href="#tutorials">← '+L('课程目录','Course index')+'</a>'}${i<data.lessons.length-1?`<a href="#learn/${data.lessons[i+1].id}">${L('下一章','Next chapter')} →</a>`:''}</div></article></div>`}
async function downloadProject(id){await load();const p=data.projects.find(x=>x.id===id);if(!p)return;const input=[...Object.entries(p.files).map(([name,data])=>({name,data})),...p.assets.map(a=>({name:a.file,data:Uint8Array.from(atob(a.base64),c=>c.charCodeAt(0))}))];const files=await RWExport.files(input);if(!files)return;const url=URL.createObjectURL(RWCore.zip(files)),a=document.createElement('a');a.href=url;a.download=p.id+'.rwmod';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ac]');if(!b)return;try{if(b.dataset.ac==='level'){level=b.dataset.value;listing()}if(b.dataset.ac==='download')await downloadProject(b.dataset.id);if(b.dataset.ac==='copy'&&active)await copy(active.sections[Number(b.dataset.index)].code);if(b.dataset.ac==='source'){const p=data.projects.find(x=>x.id===b.dataset.id),el=document.querySelector('#academy-source');el.innerHTML='<h2>'+L('完整项目代码','Complete project code')+'</h2>'+Object.entries(p.files).filter(([f])=>/\.ini$|mod-info\.txt$/.test(f)).map(([f,c])=>`<details><summary>${E(f)}</summary>${code(c,f)}</details>`).join('');el.scrollIntoView({behavior:'smooth'})}}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target.id==='academy-category'){category=e.target.value;listing()}});
window.RWAcademy={mount,downloadProject};
})();
